import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { serialize, deserialize } from 'node:v8';
import { performance } from 'node:perf_hooks';
import { setImmediate } from 'node:timers/promises';
import { createDerivedReadCache as before } from '/tmp/filtro-monthly-admission-before-20261112/derived-read-cache.js';
import { createDerivedReadCache as after } from '/home/relat/apps/filtroAPP-performance/backend/src/lib/operations/derived-read-cache.js';
import { fitsMonthlySnapshotBudget } from '/home/relat/apps/filtroAPP-performance/backend/src/lib/acompanhamento/monthly-snapshot-admission.js';

const dates = Array.from({ length: 6105 }, (_, index) => new Date(Date.UTC(2010, 0, 1 + index)).toISOString().slice(0, 10));
const build = () => {
  const rates = Array.from({ length: 64 }, (_, index) => ({ id: 'synthetic-' + index, total: .1 + .2,
    workforceDays: dates.map(date => ({ date, classification: 'WORKDAY', worked: false, conflicts: [], label: 'Dia de trabalho', calendarRevision: 1 })) }));
  return { rates, byId: new Map(rates.map(row => [row.id, row])), periodStart: new Date(dates[0]) };
};
const observations = [];
async function run(mode, round) {
  let loaderMs = 0, encodedBytes = 0, encodeMs = 0, decodeMs = 0, codecCalls = 0;
  const load = () => { const started = performance.now(); const value = build(); loaderMs += performance.now() - started; return value; };
  const cache = (mode === 'before' ? before : after)({ maxEntries: 8, maxBytes: 8 * 1024 * 1024, maxEntryBytes: 2 * 1024 * 1024,
    admitOwnedValue: fitsMonthlySnapshotBudget,
    encode: value => { const started = performance.now(); const bytes = serialize(value); codecCalls++; encodedBytes += bytes.length; encodeMs += performance.now() - started; return bytes; },
    decode: value => { const started = performance.now(); const result = deserialize(value); decodeMs += performance.now() - started; return result; } });
  const started = performance.now();
  const result = mode === 'off' ? load() : await cache.get('v', 'monthly', load);
  const totalMs = performance.now() - started;
  assert.equal(result.rates.length, 64);
  for (const row of result.rates) {
    assert.equal(result.byId.get(row.id), row);
    assert.equal(row.total, .1 + .2);
    assert.equal(row.workforceDays.length, dates.length);
    assert.equal(row.workforceDays[0].date, dates[0]);
    assert.equal(row.workforceDays.at(-1).date, dates.at(-1));
  }
  assert.ok(result.periodStart instanceof Date);
  if (mode === 'after') assert.equal(codecCalls, 0);
  observations.push({ mode, round, totalMs, loaderMs, cacheOverheadMs: totalMs - loaderMs, encodedBytes, encodeMs, decodeMs, codecCalls });
  cache.clear();
}
for (let round = 0; round < 3; round++) {
  for (const mode of round % 2 ? ['after', 'before', 'off'] : ['before', 'after', 'off']) {
    await setImmediate(); global.gc(); await run(mode, round);
  }
}
const median = rows => [...rows].sort((a, b) => a - b)[Math.floor(rows.length / 2)];
const summary = Object.fromEntries(['before', 'after', 'off'].map(mode => {
  const rows = observations.filter(row => row.mode === mode);
  return [mode, Object.fromEntries(['totalMs','loaderMs','cacheOverheadMs','encodedBytes','encodeMs','decodeMs','codecCalls'].map(key => [key, median(rows.map(row => row[key]))]))];
}));
const report = { node: process.version, syntheticOnly: true, productionAcceptance: false, rounds: 3,
  shape: { people: 64, daysPerPerson: dates.length, dayObjects: 64 * dates.length }, summary, observations };
await fs.writeFile('/tmp/filtro-monthly-admission-benchmark-20261112.json', JSON.stringify(report, null, 2));
console.log(JSON.stringify({ shape: report.shape, summary }, null, 2));
